    /** @return list<array{slug:string,name:string}> */
    public static function categories(): array
    {
        $out = [];
        foreach (self::GUIDES as $slug => $g) { $out[] = ['slug' => $slug, 'name' => $g['name']]; }
        return $out;
    }

    /** @return array{slug:string,name:string,intro:string,sections:list<array{key:string,title:string,items:list<string>}>,note:string}|null */
    public static function for(?string $categorySlug): ?array
    {
        $slug = strtolower(trim((string)$categorySlug));
        if (!isset(self::GUIDES[$slug])) { return null; }
        $g = self::GUIDES[$slug];
        $sections = [];
        foreach (self::SECTIONS as $key => $title) { $sections[] = ['key' => $key, 'title' => $title, 'items' => $g[$key]]; }
        return ['slug' => $slug, 'name' => $g['name'], 'intro' => $g['intro'], 'sections' => $sections, 'note' => self::NOTE];
    }
